style.css:
@-moz-document domain("roblox.com") {
/* ? IMAGE DE FOND */
body {
    background: url("https://i.postimg.cc/MTqBghyC/hwanxx.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
}

/* ?️ Assombrit légèrement pour lire le texte */
body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.35);
    z-index: -1;
}

/* ? Enlève les fonds blancs */
.container-main,
.content,
.game-card-container,
.home-header-container,
.section,
.roblox-game-card,
.avatar-card-container,
.friend-carousel-container {
    background: rgba(20, 20, 20, 0.55) !important;
    backdrop-filter: blur(6px);
    border-radius: 14px !important;
    border: none !important;
}

/* ? Barre du haut */
#header,
.navbar,
.navbar-fixed-top {
    background: rgba(15, 15, 15, 0.7) !important;
    backdrop-filter: blur(8px);
    border: none !important;
}

/* ? Boutons */
.btn-primary,
.btn-secondary {
    background: rgba(255, 255, 255, 0.15) !important;
    border: none !important;
    border-radius: 10px !important;
}

/* ? Texte plus doux */
body, .text, .font-header-2 {
    color: #f1f1f1 !important;
}
}
